/*
 * Platinum: a Qt application style drawing Mac OS 9.2.2's Platinum look from
 * measured pixels. Done so far: scroll bars (Smart Scrolling: both arrows at
 * the bottom/right end), push buttons (normal, pressed, disabled, default with
 * its ring), check boxes, radio buttons, pop-up menus (non-editable combo
 * boxes), sliders with tick marks, and progress bars (determinate and the
 * barber pole). Everything else is still drawn by Fusion underneath.
 *
 * Sources: docs/REFERENCE.md, docs/FINDINGS.md (scroll bar spike), and the
 * tables in slices.h / sprites.h generated by tools/gen-style-data.sh from the
 * reference captures.
 *
 * SPDX-License-Identifier: BSD-2-Clause
 */

#include "platinumstyle.h"

#include "nineslice.h"
